import java.util.PriorityQueue

data class Node(val x: Int, val y: Int, val step: Int) : Comparable<Node> {
    override fun compareTo(other: Node): Int {
        return other.step - this.step
    }
}

val vis = Array(110) { IntArray(110) }
val f = arrayOf(
    intArrayOf(0, 1),
    intArrayOf(1, 0),
    intArrayOf(0, -1),
    intArrayOf(-1, 0)
)

fun bfs(l: Int, u: Int, xi: Int, yi: Int): Int {
    val q = PriorityQueue<Node>()
    var e = Node(l, u, 0)
    q.add(e)
    vis[e.x][e.y] = 1
    while (q.isNotEmpty()) {
        e = q.poll()
        if (e.x == xi && e.y == yi) return e.step
        for (i in 0 until 4) {
            val tx = e.x + f[i][0]
            val ty = e.y + f[i][1]
            val tstep = e.step + 1
            if (tx < 0 || ty < 0) continue
            if (vis[tx][ty] != 0) continue
            vis[tx][ty] = 1
            q.add(Node(tx, ty, tstep))
        }
    }
    return -1
}

