    val s = readLine() ?: return
    val len = s.length
    var x = 0
    var y = 0
    var xx = 0
    var yy = 0
    for (i in 0 until len) {
        when (s[i]) {
            'L' -> y--
            'R' -> y++
            'U' -> x--
            'D' -> x++
        }
        xx = kotlin.math.min(xx, x)
        yy = kotlin.math.min(yy, y)
    }
    xx = -xx
    yy = -yy
    for (i in 0 until 110) {
        for (j in 0 until 110) vis[i][j] = 1
    }
    x = xx
