        when (s[i]) {
            'L' -> y--
            'R' -> y++
            'U' -> x--
            'D' -> x++
        }
        vis[x][y] = 0
    }
    val ans = bfs(xx, yy, x, y)
    if (ans == len) {
        println("OK")
    } else {
        println("BUG")
    }
}

